  window.LESSONS["u7_l14"] = {"meta":{"grade":2,"subject":"국어","term":2,"unit":7,"unit_title":"내 생각은 이래요","n":14,"covers":"14·15차시","title":"단원 마무리하기","goal":"배운 내용을 마무리할 수 있다.","std":"단원 전체 통합","duration_min":80,"lesson_format":"묶음 차시(14·15차시 연속 80분 · 정리) · 2세대 19장(7요소)","theme":"곰이·펭이 생각 나눔 교실","live_url":"../../grade2/semester2/korean/7단원_내생각은이래요/g2_kor_u7_l14_15.html","source":"grade2/semester2/korean/7단원_내생각은이래요/g2_kor_u7_l14_15.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"내 생각은 이래요\n단원 마무리하기","emoji":"🧺"},"suggested_extras":["v_l7_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 이야기 속 **인물**이 되어 「내가 만약 ~라면」 하고 생각을 정리하고, 인물 의자에서 바른 태도로 **묻고 답했어요**.","items":[{"q":"이야기 속 인물이 되어 생각할 때 어떤 틀로 말하면 좋을까요?","a":"내가 만약 ~라면 ~할 거예요. 그렇게 생각한 까닭은 ~이에요."},{"q":"같은 장면을 보고 친구와 생각이 다르면 어떻게 할까요?","a":"서로의 생각을 존중하며 나눠요"},{"q":"인물 의자에 앉은 친구에게 어떤 질문을 하면 좋을까요?","a":"인물의 생각과 까닭을 묻는 질문"}],"from":"u7_l11"},"suggested_extras":["q_l7_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"7단원 생각 바구니","kids":[{"face":"🐻","label":"곰이\n\"7단원 바구니에 무엇을 담았더라?\""},{"face":"🐧","label":"펭이\n\"글쓴이의 생각 찾기, 발표하기, 글쓰기, 댓글까지!\""}],"question":"곰이와 펭이가 7단원에서 배운 것을 바구니에서 하나씩 꺼내 보려고 해요. 7단원에서 배운 것은 무엇무엇이었을까요?","img":"assets/photo/korean/unit7_wrapup_basket.jpg","tnote":{"ask":["7단원에서 가장 기억에 남는 활동은 무엇인가요?","그 활동에서 무엇을 배웠나요?"],"watch":"","min":5}},"suggested_extras":["q_l7_2","r_l7_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"text","lines":["우리 교실에서 다육 식물을 키우면 좋겠습니다.","왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","예전에 집에서 다육 식물을 키웠는데 물을 많이 주지 않아도 잘 자라서 돌보는 일이 어렵지 않았어요.","그리고 다육 식물은 정말 귀엽게 생겨서 우리 교실의 분위기를 더 밝게 만들어 줄 거예요."]},"title":"글을 읽어요","content":"다육 식물을 키우자는 글을 한 문장씩 읽고 생각 · 까닭 · 경험 · 느낌을 찾아봐요.","tnote":{"ask":["글쓴이는 교실에서 무엇을 키우자고 했나요?","어느 문장이 까닭이고 어느 문장이 경험인가요?"],"watch":"문장 역할을 섞는 경우 — 「왜냐하면」·「예전에」 같은 말을 실마리로 짚을 것","min":10}},"src":0,"suggested_extras":["e_l7_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"note","title":"스스로 확인해요","items":["글쓴이의 생각을 찾을 수 있어요.","자신의 생각을 발표할 수 있어요.","자신의 생각을 까닭과 함께 글로 쓸 수 있어요."]},"title":"이 단원에서 나는 어떠했나요?","content":"✓**글쓴이의 생각**을 찾을 수 있어요.\n✓자신의 생각을 **발표**할 수 있어요.\n✓자신의 생각을 **까닭**과 함께 글로 쓸 수 있어요.","tnote":{"ask":["할 수 있게 된 것은 무엇인가요?","더 연습하고 싶은 것은 무엇인가요?"],"watch":"","min":6}},"src":5,"suggested_extras":["t_l7_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"제목","emoji":"🏷️"},{"name":"생각","emoji":"💭"},{"name":"까닭","emoji":"❓"}]},"title":"글씨를 바르게 따라 써 봐요 (글자를 눌러요)","content":"따라 쓰기: 제목 · 생각 · 까닭","tnote":{"ask":["어떤 낱말을 따라 쓰나요?","「까닭」은 무엇을 뜻하는 말이었나요?"],"watch":"칸을 벗어나 크게 쓰는 경우 — 칸에 맞추어 또박또박 쓰게 할 것","min":8}},"src":10,"suggested_extras":["e_l7_2","t_l7_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"chain","items":[{"name":"가족과 지키고 싶은 일","emoji":"🏠"},{"name":"~하자","emoji":"💭"},{"name":"왜냐하면 ~이기 때문이에요","emoji":"❓"}]},"title":"오늘 집에서 실천해 봐요","content":"🏠 오늘 저녁, 가족에게 우리 집에서 함께 지키고 싶은 일 한 가지를 「~하자. 왜냐하면 ~이기 때문이에요.」처럼 까닭과 함께 말해 보세요.","tnote":{"ask":["우리 집에서 함께 지키고 싶은 일은 무엇인가요?","그 까닭은 무엇인가요?"],"watch":"까닭 없이 「~하자」만 말하는 경우 — 「왜냐하면」을 붙이게 할 것","min":6}},"src":11,"suggested_extras":["q_l7_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"「맑네」는 [망네]로 소리 나니까 쓸 때도 「**망네**」라고 쓴다.","right":"「맑네」는 [망네]로 소리 나지만 **글자는 「맑네」 그대로** 써요. 「괜찮아」·「숲이」도 **소리와 글자가 달라요**.","hint":"칠판에 「망네」와 「맑네」를 나란히 쓰고 어느 쪽이 바르게 쓴 것인지 고르게 하세요. 그다음 소리 내어 읽어 소리가 같은지 느끼게 하세요.","tnote":{"ask":["「맑네」는 어떻게 소리 날까요?","소리와 글자가 다른 낱말을 또 알고 있나요?"],"watch":"들리는 대로 받아 적는 경우","min":4}},"suggested_extras":["x_l7_1","x_l7_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🪴","body":"곰이가 다육 식물 글에서 글쓴이의 생각을 찾고 있어요."},"question":"글쓴이의 생각은?","options":[{"text":"물을 많이 주지 말자"},{"text":"집에서 식물을 키우자"},{"text":"교실에서 다육 식물을 키우자","correct":true}],"note":"풀이: 그림과 상황을 떠올려요. → **교실에서 다육 식물을 키우자**"},"src":1,"suggested_extras":["t_l7_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"💭","body":"펭이가 자신의 생각을 표현하는 문장을 고르고 있어요."},"question":"자신의 생각을 표현하는 문장을 모두 골라요","options":[{"text":"놀이할 때 규칙을 지키자.","correct":true},{"text":"점심시간에 운동장에서 축구하는 건 어때?","correct":true},{"text":"지금 다섯 시야."},{"text":"이 아이스크림은 오백 원이야."},{"text":"교실 문을 닫고 다니자.","correct":true},{"text":"물을 낭비하지 말자.","correct":true}],"multi":true,"note":"풀이: 그림과 상황을 떠올려요. → 알맞은 것 **4개**"},"src":3,"suggested_extras":["e_l7_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🌳","body":"곰이가 「숲이」를 소리 내어 읽고 있어요."},"question":"「숲이」의 소리로 알맞은 것은?","options":[{"text":"[숲이]"},{"text":"[수피]","correct":true},{"text":"[숩피]"}],"note":"풀이: 그림과 상황을 떠올려요. → **[수피]**"},"src":9,"suggested_extras":["q_l7_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"「「괜찮아」는 [○○○]로 소리 나요.」 빈칸에 알맞은 소리를 넣어 읽어 봐요.","a":"괜차나","steps":["「괜찮아」를 천천히 소리 내어 읽는다","들리는 소리를 떠올린다","빈칸에 넣어 끝까지 소리 내어 읽는다"]},"도전":{"q":"다육 식물 글에서 생각 · 까닭 · 경험 · 느낌에 해당하는 문장을 하나씩 찾아 말해 봐요.","a":"생각 — 교실에서 다육 식물을 키우면 좋겠다 / 까닭 — 키우기가 쉽기 때문 / 경험 — 집에서 키웠는데 잘 자랐다 / 느낌 — 교실 분위기를 밝게 만들어 줄 것","steps":["글을 한 문장씩 다시 읽는다","「왜냐하면」·「예전에」 같은 말을 찾는다","문장마다 하는 일을 말한다"]},"심화":{"q":"다육 식물을 키우자는 글쓴이의 생각에 대한 내 생각을 까닭과 함께 글로 써 봐요.","a":"여러 답 (예: 저도 키우고 싶어요. 왜냐하면 귀여운 식물을 보면 기분이 좋아지기 때문이에요.)","open":true}},"tnote":{"ask":["기본에서 빈칸을 채워 끝까지 읽었나요?","심화에서 까닭을 함께 썼나요?"],"watch":"도전에서 경험과 느낌을 섞는 경우 — 「예전에」로 시작하는 문장을 짚게 할 것","min":8}},"suggested_extras":["q_l7_5","g_l7_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"7단원 생각 바구니 놀이","type":"group","goal":"모둠이 「글쓴이의 생각」·「발표」·「글쓰기」·「댓글」 주제 카드를 하나씩 뽑아, 뽑은 주제로 배운 것 한 가지와 7단원 속 예 하나를 말하고 다른 친구가 덧붙이기","steps":["주제 카드 넷을 뒤집어 놓고 하나씩 뽑는다","뽑은 주제로 배운 것 한 가지를 말한다","7단원에서 읽은 글이나 한 활동에서 예를 하나 든다","다른 친구가 하나를 덧붙여 말한다"],"solo":["주제 카드 넷을 차례로 뒤집는다","주제마다 배운 것 한 가지와 7단원 속 예 하나를 소리 내어 말한다"],"materials":["주제 카드 4장","생각 바구니 판"],"minutes":18,"tnote":{"ask":["가장 쉽게 말한 주제는 무엇이었나요?","친구가 덧붙인 말 가운데 새로 안 것은 무엇인가요?"],"watch":"예를 들지 못하는 경우 — 차시 글 판을 다시 보여 줄 것","min":18}},"suggested_extras":["g_l7_2","t_l7_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"가족이 고른 글 읽기","scenario":{"icon":"📰","body":"가족에게 신문 기사나 책에서 생각이 담긴 짧은 글을 하나 골라 달라고 부탁해 보아요. 함께 읽고 글쓴이의 생각을 찾은 뒤, 그 생각에 대한 내 생각을 까닭과 함께 말해 보아요."},"content":"글쓴이의 생각을 **찾고**, 내 생각을 **까닭**과 함께 **말과 글**로 나타내요."},"suggested_extras":["r_l7_2","r_l7_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"펭이가 7단원을 「글쓴이의 생각은 글 첫 문장만 보면 알고, 내 생각은 까닭 없이 써도 돼.」라고 정리했어요.","challenge":"펭이의 정리에서 알맞지 않은 곳 두 군데를 찾아 바르게 고쳐 말해 봐요.","note":"풀이: 글쓴이의 생각은 **제목과 여러 중심 생각을 모아** 찾아요. 내 생각을 쓸 때는 **까닭**을 함께 써야 읽는 사람이 잘 이해해요.","tnote":{"ask":["펭이의 정리에서 알맞지 않은 곳은 어디인가요?","바르게 고친 정리를 말해 볼까요?"],"watch":"한 군데만 고치고 끝내는 경우","min":5}},"suggested_extras":["t_l7_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"「맑네」는 어떻게 소리 내고 어떻게 쓸까요?","a":"[망네]로 소리 내고 「맑네」로 써요"},{"q":"자신의 생각을 나타내는 문장은 어떻게 끝날 때가 많을까요?","a":"「~하자」, 「~는 어때?」처럼 끝나요"},{"q":"7단원에서 배운 것 가운데 하나를 말해 볼까요?","a":"글쓴이의 생각 찾기 · 내 생각 발표하기 · 생각을 글로 쓰기"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["🔎 제목과 중심 생각으로 **글쓴이의 생각**을 찾았어요.","🎤 내 생각을 바른 태도로 **발표**했어요.","✍️ 생각·까닭·경험·느낌으로 **글**을 썼어요.","곰이와 펭이는 7단원 바구니를 정리하며 「생각에는 언제나 까닭을 함께!」라고 말했다."],"arrows":["글쓴이의 생각 찾기","까닭을 넣어 말하고 쓰기","다음: 8단원 「나도 작가」"]},"suggested_extras":["r_l7_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 글쓴이의 생각을 찾을 수 있나요?","🔧 과정·기능 — 내 생각을 까닭과 함께 말하고 쓸 수 있나요?","💛 가치·태도 — 다른 사람의 생각을 존중하려고 했나요?"],"prompts":["7단원에서 배운 것 가운데 앞으로 가장 많이 쓰고 싶은 것은 무엇인가요?"]},"suggested_extras":["e_l7_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"8단원 「나도 작가」를 시작해요. 좋아하는 노래의 가사를 바꾸어 불러 본 적이 있나요?","emoji":"📚"},"suggested_extras":["c_l7_1"]}],"extras":[{"id":"v_l7_1","type":"video","icon":"🎥","title":"7단원 마무리 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+2%ED%95%99%EB%85%84+%EA%B5%AD%EC%96%B4+%EC%83%9D%EA%B0%81+%EA%B9%8C%EB%8B%AD+%EB%A7%88%EB%AC%B4%EB%A6%AC","description":"생각과 까닭을 말하고 쓰는 법을 되짚는 영상(교사가 먼저 확인).","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l7_1","type":"fun_question","icon":"💡","title":"기억에 남는 활동","content":"7단원에서 가장 기억에 남는 활동은 무엇인가요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_2","type":"fun_question","icon":"💡","title":"다육 식물","content":"교실에서 다육 식물을 키우는 것에 대한 내 생각은 무엇인가요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_3","type":"fun_question","icon":"💡","title":"소리와 글자","content":"「숲이」를 소리 나는 대로 쓰면 어떻게 될까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_4","type":"fun_question","icon":"💡","title":"생각 문장","content":"「지금 다섯 시야.」는 생각을 나타내는 문장일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_5","type":"fun_question","icon":"💡","title":"실천할 일","content":"우리 집에서 함께 지키고 싶은 일은 무엇인가요?","fit_slides":["concept","basic_problem"]},{"id":"t_l7_1","type":"tip","icon":"🧩","title":"주제 카드","content":"글쓴이의 생각 · 발표 · 글쓰기 · 댓글 카드를 미리 만들어 두세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_2","type":"tip","icon":"🧩","title":"문장 역할 찾기","content":"다육 식물 글의 문장마다 역할 붙임딱지를 붙이게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_3","type":"tip","icon":"🧩","title":"소리 내어 견주기","content":"소리와 글자가 다른 낱말은 소리 내어 읽은 뒤 글자를 보게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_4","type":"tip","icon":"🧩","title":"점검은 나만 보기","content":"스스로 확인은 점수가 아니라 나만 보는 확인임을 알려 주세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_5","type":"tip","icon":"🧩","title":"다음 단원 예고","content":"다음 시간은 8단원 「나도 작가」를 시작해요.","fit_slides":["concept","misconception"]},{"id":"r_l7_1","type":"real_world","icon":"🌍","title":"가족이 고른 글","content":"가족이 고른 글에서 글쓴이의 생각을 찾아요.","fit_slides":["real_world","summary"]},{"id":"r_l7_2","type":"real_world","icon":"🌍","title":"우리 집 약속","content":"우리 집 약속을 까닭과 함께 말해요.","fit_slides":["real_world","summary"]},{"id":"r_l7_3","type":"real_world","icon":"🌍","title":"간판 소리","content":"간판 낱말 가운데 소리와 글자가 다른 것을 찾아요.","fit_slides":["real_world","summary"]},{"id":"g_l7_1","type":"game","icon":"🎮","title":"생각 바구니","content":"주제 카드를 뽑아 배운 것을 말해요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l7_2","type":"game","icon":"🎮","title":"생각 문장 찾기","content":"문장 카드에서 생각을 나타내는 문장을 골라요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l7_1","type":"misconception","icon":"⚠️","title":"소리 나는 대로","content":"소리 나는 대로 받아 쓰는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l7_2","type":"misconception","icon":"⚠️","title":"까닭 빼기","content":"내 생각을 까닭 없이 쓰는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l7_1","type":"example","icon":"📝","title":"다육 식물 글 판","content":"다육 식물을 키우자는 글 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l7_2","type":"example","icon":"📝","title":"따라 쓰기 칸","content":"제목 · 생각 · 까닭 따라 쓰기 칸을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l7_3","type":"example","icon":"📝","title":"생각 바구니 판","content":"주제 카드를 붙일 생각 바구니 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l7_1","type":"checklist","icon":"✅","title":"다음 차시 준비","content":"다음 시간은 8단원 「나도 작가」를 시작해요. 교과서 228쪽부터 펴 두세요.","fit_slides":["next_lesson"]}]};
